      "capacidad_decision_estimada": {"type": "string"},
      "contactabilidad": {"type": "string"},
      "busqueda_contacto_requerida": {"type": "boolean"},
      "datos_contacto_faltantes": {
        "type": "array",
        "items": {"type": "string"}
      },
      "fuentes": {
        "type": "array",
        "items": {"type": "string"}
      },
      "motivo_prioridad": {"type": "string"},
      "accion_recomendada": {"type": "string"},
      "datos_faltantes": {
        "type": "array",
        "items": {"type": "string"}
      },
      "resumen_comercial": {"type": "string"}
    },
    "required": [
      "empresa",
